﻿import React from 'react';
import {AbsoluteFill, interpolateColors} from 'remotion';
import {useS, en, Camara, Subtitulos, Textura, Profundidad, Brillo, Paso, seguir, enCamino, tono, Chip, Contador, Ondas, Destello, golpe, h, clamp, interpolate, Easing} from './kit';

export const SUBS = {arriba: 230, acento: '#E7FF00'};

// ---- tiempos atados a la voz ----
const ATACA = en('ataca'), DENTRO = en('Dentro'), ACIDO = en('ácido'), CARNE = en('carne'), SUS = en('sus'), PAREDES = en('paredes');
const ENTONCES = en('Entonces'), DESHACE = en('deshace'), CERCA = en('cerca'), MOCO = en('moco'), BICARB = en('bicarbonato');
const POLVO = en('polvo'), HORNEAR = en('hornear'), JUSTO = en('Justo'), PARED2 = en('pared', 2), APAGA = en('apaga');
const ALGO = en('algo'), QUEMA = en('quema'), NO2 = en('no', 2), REPARA = en('repara'), CAMBIA = en('cambia');
const CADA = en('Cada'), DIAS = en('días'), MUEREN = en('mueren'), SUELTAN = en('sueltan'), CAEN = en('caen');
const ABAJO = en('abajo'), SUBEN = en('suben'), SITIO = en('sitio'), NACISTE = en('naciste'), CIENTOS = en('cientos');
const ASI = en('Así'), ATACA2 = en('ataca', 2), GANA = en('gana'), HIERRO = en('hierro'), ESTRENA = en('estrena');

const VERDE = '#C8E04A', AZUL = '#7FC8FF', QUEMADO = '#D9701E', LIMA = '#E7FF00';

const Lienzo: React.FC<{children: React.ReactNode}> = ({children}) => <svg width={1080} height={1920} style={{position: 'absolute', inset: 0}}>{children}</svg>;

// Protagonista: la gota de ácido (punta arriba), con luz y sombra, siempre la misma.
const Gota: React.FC<{x: number; y: number; r?: number; col?: string; sx?: number; sy?: number; op?: number; ang?: number}> = ({x, y, r = 60, col = VERDE, sx = 1, sy = 1, op = 1, ang = 0}) => (
  <g transform={`translate(${x} ${y}) rotate(${ang}) scale(${sx} ${sy})`} opacity={op}>
    <defs>
      <radialGradient id="gLuz" cx="35%" cy="35%" r="65%"><stop offset="0%" stopColor="rgba(255,255,255,0.8)" /><stop offset="45%" stopColor="rgba(255,255,255,0.12)" /><stop offset="100%" stopColor="rgba(255,255,255,0)" /></radialGradient>
      <radialGradient id="gSombra" cx="50%" cy="50%" r="60%"><stop offset="55%" stopColor="rgba(0,0,0,0)" /><stop offset="100%" stopColor="rgba(20,30,0,0.5)" /></radialGradient>
    </defs>
    <circle r={r * 2.3} fill={col} opacity={0.22} />
    <path d={`M 0 ${-r * 1.55} C ${r * 0.95} ${-r * 0.2} ${r * 1.05} ${r * 0.95} 0 ${r} C ${-r * 1.05} ${r * 0.95} ${-r * 0.95} ${-r * 0.2} 0 ${-r * 1.55} Z`} fill={col} stroke="rgba(40,60,0,0.55)" strokeWidth={4} />
    <path d={`M 0 ${-r * 1.55} C ${r * 0.95} ${-r * 0.2} ${r * 1.05} ${r * 0.95} 0 ${r} C ${-r * 1.05} ${r * 0.95} ${-r * 0.95} ${-r * 0.2} 0 ${-r * 1.55} Z`} fill="url(#gSombra)" />
    <path d={`M 0 ${-r * 1.55} C ${r * 0.95} ${-r * 0.2} ${r * 1.05} ${r * 0.95} 0 ${r} C ${-r * 1.05} ${r * 0.95} ${-r * 0.95} ${-r * 0.2} 0 ${-r * 1.55} Z`} fill="url(#gLuz)" />
    <ellipse cx={-r * 0.38} cy={-r * 0.1} rx={r * 0.16} ry={r * 0.34} fill="#fff" opacity={0.85} transform={`rotate(18 ${-r * 0.38} ${-r * 0.1})`} />
  </g>
);

// ---- estómago por dentro (pliegues húmedos + lago de ácido) ----
const Pliegues: React.FC<{claro?: boolean; halo?: number; metal?: number}> = ({claro, halo = 0, metal = 0}) => {
  const {s} = useS();
  return (
    <>
      <Textura tipo="piel" base={claro ? 'radial-gradient(circle at 50% 40%, #F29C8E, #B8504E 65%, #5A1E26)' : 'radial-gradient(circle at 50% 40%, #E8857A, #9E3B3B 65%, #4A1620)'} linea="rgba(90,20,30,0.55)" luz="rgba(255,205,195,0.28)" semilla={4} />
      <Lienzo>
        {Array.from({length: 7}).map((_, i) => {
          const y0 = 60 + i * 230 + Math.sin(s * 1.1 + i * 1.3) * 14;
          const d = `M -80 ${y0} C 220 ${y0 - 150} 640 ${y0 + 160} 1160 ${y0 - 60}`;
          return (
            <g key={i}>
              <path d={d} stroke="#5E1F26" strokeWidth={188} fill="none" opacity={0.55} transform="translate(0 16)" />
              <path d={d} stroke={i % 2 ? '#B04A48' : '#C25852'} strokeWidth={170} fill="none" />
              <path d={d} stroke="#F7B0A4" strokeWidth={44} fill="none" opacity={0.42 + halo * 0.5} transform="translate(0 -38)" />
              <path d={d} stroke="#FFF1EA" strokeWidth={9} fill="none" opacity={0.5} transform="translate(0 -50)" strokeLinecap="round" strokeDasharray="60 90" />
            </g>
          );
        })}
        {Array.from({length: 9}).map((_, i) => <ellipse key={i} cx={h(i * 3 + 1) * 1000 + 40} cy={h(i * 5 + 2) * 1250 + 60} rx={10 + h(i) * 14} ry={5 + h(i * 2) * 7} fill="#fff" opacity={0.45 + Math.sin(s * 2 + i) * 0.2} />)}
      </Lienzo>
      {halo > 0 && <Brillo x={540} y={720} r={520} color={`rgba(255,150,135,${0.65 * halo})`} />}
      {metal > 0 && (
        <AbsoluteFill style={{pointerEvents: 'none'}}>
          <div style={{position: 'absolute', inset: 0, background: 'rgba(170,185,200,0.55)', opacity: Math.sin(metal * Math.PI) * 0.9, mixBlendMode: 'overlay'}} />
          <div style={{position: 'absolute', left: -700 + metal * 2300, top: 0, width: 520, height: 1500, transform: 'skewX(-18deg)', background: 'linear-gradient(90deg, transparent, rgba(235,242,250,0.85) 40%, rgba(255,255,255,0.95) 50%, rgba(140,155,170,0.7) 62%, transparent)', opacity: 0.9}} />
        </AbsoluteFill>
      )}
    </>
  );
};

const Lago: React.FC<{y0?: number}> = ({y0 = 1400}) => {
  const {s} = useS();
  const pts: string[] = [];
  for (let x = 0; x <= 1080; x += 40) pts.push(`${x},${y0 + Math.sin(x * 0.02 + s * 2) * 14}`);
  return (
    <Lienzo>
      <defs><linearGradient id="lagoG" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#D7EE5C" stopOpacity={0.95} /><stop offset="100%" stopColor="#5B7A12" stopOpacity={0.98} /></linearGradient></defs>
      <polygon points={`${pts.join(' ')} 1080,1960 0,1960`} fill="url(#lagoG)" />
      <polyline points={pts.join(' ')} fill="none" stroke="#F2FFA0" strokeWidth={6} opacity={0.8} />
      {Array.from({length: 16}).map((_, i) => {
        const r = 8 + h(i * 3) * 22;
        const y = y0 + 520 - ((s * (50 + h(i) * 70) + h(i * 7) * 520) % 520);
        return <circle key={i} cx={h(i) * 1040 + 20 + Math.sin(s * 2 + i) * 10} cy={y} r={r} fill="rgba(255,255,200,0.25)" stroke="rgba(255,255,230,0.7)" strokeWidth={3} />;
      })}
    </Lienzo>
  );
};

const Carne: React.FC<{x: number; y: number; t0: number}> = ({x, y, t0}) => {
  const {s, spr} = useS();
  const e = spr(t0, 12, 120);
  if (e <= 0.001) return null;
  const p = interpolate(s, [t0 + 0.2, t0 + 1.8], [0, 1], clamp);
  return (
    <g transform={`translate(${x} ${y + Math.sin(s * 2.4) * 8}) rotate(${-8 + Math.sin(s * 1.6) * 6}) scale(${e * (1 - p * 0.35)})`}>
      <path d="M -120 -40 C -100 -110 40 -120 110 -60 C 150 -10 120 80 40 100 C -50 120 -140 70 -120 -40 Z" fill="#C0394B" stroke="#6E1424" strokeWidth={6} />
      <path d="M -80 -30 C -30 -60 40 -50 80 -20" stroke="#F3C8C8" strokeWidth={14} fill="none" strokeLinecap="round" opacity={0.8} />
      <path d="M -70 30 C -20 10 40 30 90 10" stroke="#F3C8C8" strokeWidth={10} fill="none" strokeLinecap="round" opacity={0.6} />
      {Array.from({length: 7}).map((_, i) => {
        const L = 20 + p * (110 + h(i) * 90);
        const y0 = -60 + i * 24;
        return <path key={i} d={`M 100 ${y0} q ${L * 0.4} ${(i % 2 ? 22 : -22)} ${L} ${(i - 3) * 9}`} stroke="#E36A7C" strokeWidth={8} fill="none" strokeLinecap="round" opacity={0.25 + p * 0.75} />;
      })}
    </g>
  );
};

// Sitio 1: dentro del estómago (E1-E4)
const EstomagoIni: React.FC = () => {
  const {s, lin} = useS();
  // gota
  let gx = 540, gy = 200, sx = 1, sy = 1, gr = 62;
  if (s < ATACA) {
    const k = Math.max(0, s / ATACA);
    gy = 200 + 505 * k * k;
    sy = 1 + 0.15 * k;
  } else if (s < ACIDO + 0.6) {
    const q = lin(ATACA, ATACA + 0.3, 0, 1);
    const rec = lin(ATACA + 0.3, DENTRO + 0.5, 0, 1);
    const baja = lin(DENTRO, ACIDO, 0, 1, Easing.in(Easing.quad));
    gy = 705 + baja * 690;
    sx = 1 + 0.7 * q * (1 - rec);
    sy = 1 - 0.65 * q * (1 - rec);
  } else if (s < ENTONCES - 0.3) {
    gx = 540 + Math.sin(s * 1.4) * 40;
    gy = 1440 + Math.sin(s * 2.2) * 16;
  } else {
    const k = lin(ENTONCES - 0.3, DESHACE, 0, 1);
    gx = 540 + k * 190;
    gy = 1440 - k * 480 + Math.sin(s * 3) * 10;
    gr = 62 + k * 16;
  }
  const dt = s - ATACA;
  const splash = dt > 0 && dt < 1.2;
  return (
    <AbsoluteFill>
      <Pliegues halo={interpolate(s, [PAREDES, PAREDES + 0.5, PAREDES + 2.5], [0, 1, 0.3], clamp)} />
      <Lago />
      <Brillo x={540} y={1560} r={430} color="rgba(200,224,74,0.35)" />
      {/* mancha de ácido quemando la pared */}
      {s > ATACA && <Lienzo><circle cx={540} cy={712} r={interpolate(s, [ATACA, ATACA + 0.5], [10, 120], clamp)} fill={QUEMADO} opacity={0.55} /><circle cx={540} cy={712} r={interpolate(s, [ATACA, ATACA + 0.5], [6, 60], clamp)} fill="#5A2208" opacity={0.6} /></Lienzo>}
      <Lienzo>
        {splash && Array.from({length: 10}).map((_, i) => {
          const a = (-170 + i * 22) * Math.PI / 180;
          const v = 380 + h(i * 3) * 360;
          return <circle key={i} cx={540 + Math.cos(a) * v * dt} cy={712 + Math.sin(a) * v * dt + 1100 * dt * dt} r={16 - dt * 8} fill={VERDE} opacity={Math.max(0, 1 - dt / 1.1)} />;
        })}
        {dt > 0 && dt < 0.7 && Array.from({length: 14}).map((_, i) => {
          const a = (i / 14) * Math.PI * 2;
          const v = 220 + h(i * 5) * 300;
          return <circle key={'c' + i} cx={540 + Math.cos(a) * v * dt} cy={712 + Math.sin(a) * v * dt} r={5 + h(i) * 5} fill="#FFF2A0" opacity={1 - dt / 0.7} />;
        })}
        <Carne x={600} y={1470} t0={CARNE} />
        <Gota x={gx} y={gy} r={gr} sx={sx} sy={sy} />
      </Lienzo>
      <Ondas x={540} y={712} t0={ATACA} color={VERDE} radio={320} />
      <Ondas x={540} y={1440} t0={ACIDO} color="#F2FFA0" radio={260} />
      <Destello t0={ATACA} fuerza={0.28} />
      <Chip texto="?" x={540} y={740} t0={ENTONCES} size={150} color={LIMA} />
    </AbsoluteFill>
  );
};

// Sitio 2: corte de la pared en capas, como lámina médica (E5-E11)
const SLOTS = [1, 3, 7];
const CX = (i: number) => 60 + i * 120;
const CRACK: [number, number][] = [[700, 400], [690, 560], [672, 680], [690, 780], [660, 880]];

const Celda: React.FC<{cx: number; y: number; fill: string; w?: number; hh?: number; op?: number; rot?: number; sc?: number}> = ({cx, y, fill, w = 104, hh = 190, op = 1, rot = 0, sc = 1}) => (
  <g transform={`translate(${cx} ${y + hh / 2}) rotate(${rot}) scale(${sc})`} opacity={op}>
    <rect x={-w / 2} y={-hh / 2} width={w} height={hh} rx={40} fill={fill} stroke="rgba(70,15,25,0.7)" strokeWidth={5} />
    <rect x={-w / 2 + 10} y={-hh / 2 + 12} width={14} height={hh - 40} rx={7} fill="#fff" opacity={0.22} />
    <ellipse cx={0} cy={hh * 0.14} rx={22} ry={30} fill="rgba(90,20,40,0.55)" />
  </g>
);

const Corte: React.FC = () => {
  const {s, spr, lin} = useS();
  const T = enCamino(s, CRACK, ALGO - 0.1, QUEMA - 0.05);
  const paradas = [
    {t: CERCA, x: 540, y: 960, zoom: 1.0},
    {t: MOCO, x: 540, y: 790, zoom: 1.2},
    {t: HORNEAR, x: 540, y: 720, zoom: 1.45},
    {t: JUSTO + 0.2, x: 560, y: 500, zoom: 1.3},
    {t: ALGO - 0.6, x: 560, y: 500, zoom: 1.3},
    ...seguir(CRACK, ALGO - 0.1, QUEMA - 0.05, 1.4, 5),
    {t: CAMBIA, x: 650, y: 930, zoom: 1.45},
    {t: CAMBIA + 1.6, x: 640, y: 940, zoom: 1.5},
    {t: CADA, x: 600, y: 900, zoom: 1.45},
    {t: DIAS + 0.6, x: 540, y: 880, zoom: 1.0},
    {t: MUEREN, x: 540, y: 900, zoom: 1.2},
    {t: ABAJO, x: 540, y: 1050, zoom: 1.3},
    {t: SITIO, x: 540, y: 900, zoom: 1.3},
  ];
  // gota protagonista
  const idle = {x: 260 + Math.sin(s * 1.3) * 30, y: 300 + Math.sin(s * 2) * 14};
  const kk = lin(JUSTO, PARED2, 0, 1, Easing.in(Easing.quad));
  let gx = idle.x + (540 - idle.x) * kk, gy = idle.y + (478 - idle.y) * kk, gr = 56 + 24 * kk;
  let sq = 1;
  if (s > PARED2) {
    gx = 540; gy = 478 + 40 * lin(APAGA, APAGA + 1.2, 0, 1);
    gr = 80 * (1 - 0.45 * lin(APAGA, APAGA + 1.2, 0, 1));
    sq = 1 - 0.3 * Math.min(1, golpe(s, PARED2, 20, 5) ** 2 * 4) - 0.25 * lin(APAGA, APAGA + 0.8, 0, 1);
  }
  const gcol = tono(s, [0, APAGA, APAGA + 0.9], [VERDE, '#A9B49A', AZUL], 0.6);
  // células
  const sup = (i: number) => {
    const nuevo = interpolateColors(Math.max(0, Math.min(1, (s - CADA - i * 0.18) / 0.9)), [0, 1], ['#C95F5A', '#F7B8AE']);
    const base = s < CADA ? '#C95F5A' : nuevo;
    if (i === 5) {
      if (s < QUEMA) return <Celda key={i} cx={CX(i)} y={860} fill={base} />;
      const q = interpolateColors(Math.max(0, Math.min(1, (s - QUEMA) / 0.7)), [0, 1], [base, '#7A3512']);
      if (s < CAMBIA) return <Celda key={i} cx={CX(i)} y={860} fill={q} rot={golpe(s, QUEMA, 30, 6) * 4} />;
      const p = lin(CAMBIA, CAMBIA + 1.3, 0, 1, Easing.in(Easing.quad));
      const hoy = interpolateColors(Math.max(0, Math.min(1, (s - CADA - 5 * 0.18) / 0.9)), [0, 1], ['#C95F5A', '#F7B8AE']);
      return (
        <g key={i}>
          <rect x={CX(i) - 52} y={860} width={104} height={190} rx={40} fill="rgba(60,15,25,0.55)" />
          {s > CADA + 0.9 && <Celda cx={CX(i)} y={860} fill={hoy} sc={spr(CADA + 0.9, 12, 120)} />}
          <Celda cx={CX(i)} y={860 - p * 360} fill={q} rot={p * 50} op={1 - p} sc={1 - 0.3 * p} />
        </g>
      );
    }
    if (SLOTS.includes(i)) {
      const dead = s >= MUEREN ? interpolateColors(Math.max(0, Math.min(1, (s - MUEREN) / 0.6)), [0, 1], ['#F7B8AE', '#8C5A4A']) : '#F7B8AE';
      const c0 = s < CADA ? '#C95F5A' : s < MUEREN ? base : dead;
      const wig = s > SUELTAN && s < CAEN ? golpe(s, SUELTAN, 22, 2.5) * 7 : 0;
      const p = lin(CAEN, CAEN + 1.4, 0, 1, Easing.in(Easing.quad));
      const e = lin(ABAJO, SITIO, 0, 1);
      return (
        <g key={i}>
          <rect x={CX(i) - 52} y={860} width={104} height={190} rx={40} fill="rgba(60,15,25,0.5)" />
          {s >= SITIO - 0.1 && <Celda cx={CX(i)} y={860} fill="#FFC9C0" />}
          {s < CAEN + 1.5 && <Celda cx={CX(i)} y={860 - p * 380} fill={c0} rot={wig + p * 40 * (i % 2 ? 1 : -1)} op={1 - interpolate(s, [CAEN + 0.7, CAEN + 1.5], [0, 1], clamp)} sc={1 - 0.35 * p} />}
          {e > 0 && e < 1 && <circle cx={CX(i)} cy={955 + (1 - e) * 190} r={110} fill="rgba(255,225,215,0.3)" />}
        </g>
      );
    }
    return <Celda key={i} cx={CX(i)} y={860} fill={base} />;
  };
  const fila2 = (i: number) => {
    if (SLOTS.includes(i)) {
      const e = lin(ABAJO, SITIO, 0, 1, Easing.inOut(Easing.cubic));
      return (
        <g key={'f' + i}>
          <rect x={CX(i) - 52} y={1050} width={104} height={190} rx={40} fill="rgba(50,12,20,0.7)" />
          {e < 1 && s < SITIO + 0.1 && <Celda cx={CX(i)} y={1050 - e * 190} fill="#FFC9C0" />}
        </g>
      );
    }
    return <Celda key={'f' + i} cx={CX(i)} y={1050} fill="#EE9A90" />;
  };
  const gelOp = 0.5 + 0.4 * lin(MOCO, MOCO + 0.7, 0, 1);
  const hum = s > QUEMA ? s - QUEMA : -1;
  return (
    <AbsoluteFill style={{background: '#2a0c14'}}>
      <Camara paradas={paradas}>
        <Textura tipo="celulas" base="radial-gradient(circle at 50% 70%, #E8857A, #9E3B3B 70%, #3a1018)" linea="rgba(80,20,30,0.6)" luz="rgba(255,200,190,0.22)" semilla={7} />
        <Lienzo>
          {Array.from({length: 9}).map((_, i) => <Celda key={'t' + i} cx={CX(i)} y={1240} fill="#D77A74" />)}
          {Array.from({length: 9}).map((_, i) => fila2(i))}
          {Array.from({length: 9}).map((_, i) => sup(i))}
          {/* lumen: ácido arriba */}
          <defs>
            <linearGradient id="lumenG" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#1B2A0A" /><stop offset="100%" stopColor="#6E8E1A" /></linearGradient>
            <linearGradient id="gelG" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#B8E4FF" stopOpacity={0.9} /><stop offset="100%" stopColor="#4C9BE0" stopOpacity={0.85} /></linearGradient>
          </defs>
          <rect x={-100} y={-900} width={1280} height={1460} fill="url(#lumenG)" />
          {Array.from({length: 14}).map((_, i) => <circle key={'lb' + i} cx={h(i) * 1060 + 10} cy={560 - ((s * (30 + h(i * 3) * 40) + h(i * 5) * 700) % 700)} r={8 + h(i * 7) * 18} fill="rgba(235,255,150,0.2)" stroke="rgba(235,255,170,0.55)" strokeWidth={3} />)}
          <g opacity={gelOp}>
            <path d={`M -20 ${560 + Math.sin(s * 1.6) * 6} Q 135 ${530 + Math.sin(s * 1.6 + 1) * 10} 270 560 T 540 560 T 810 560 T 1100 560 L 1100 880 L -20 880 Z`} fill="url(#gelG)" stroke="#D8F0FF" strokeWidth={6} />
            <ellipse cx={300} cy={620} rx={180} ry={22} fill="#fff" opacity={0.35} />
            <ellipse cx={820} cy={650} rx={130} ry={16} fill="#fff" opacity={0.28} />
          </g>
          {/* burbujitas de bicarbonato dentro del gel */}
          {s > BICARB - 0.1 && Array.from({length: 20}).map((_, i) => {
            const r = 6 + h(i * 3) * 9;
            const y = 850 - (((s - BICARB) * (40 + h(i) * 40) + h(i * 7) * 260) % 260);
            return <circle key={'bb' + i} cx={50 + h(i) * 980} cy={y} r={r * spr(BICARB + i * 0.04, 14, 140)} fill="rgba(255,255,255,0.85)" stroke="#BFE6FF" strokeWidth={2} opacity={interpolate(y, [585, 620], [0, 1], clamp)} />;
          })}
          {/* grieta y gotita */}
          {s > ALGO - 0.1 && <polyline points={CRACK.map((p) => p.join(',')).join(' ')} fill="none" stroke="#2C5C8C" opacity={1 - lin(CAMBIA + 0.5, CAMBIA + 1.5, 0, 1)} strokeWidth={16} strokeLinecap="round" strokeLinejoin="round" pathLength={1} strokeDasharray={`${T.p} 1`} />}
          {/* cucharita a escala */}
          {s > POLVO - 0.1 && s < JUSTO + 0.3 && (
            <g transform={`translate(800 360) rotate(-28) scale(${spr(POLVO, 12, 130) * (1 - lin(JUSTO - 0.2, JUSTO + 0.3, 0, 1))})`}>
              <rect x={0} y={-12} width={300} height={24} rx={12} fill="#C9CED6" stroke="#7D8590" strokeWidth={4} />
              <ellipse cx={-20} cy={0} rx={80} ry={52} fill="#DFE4EB" stroke="#7D8590" strokeWidth={5} />
              <path d="M -86 -4 Q -20 -86 48 -4 Z" fill="#fff" />
              {Array.from({length: 9}).map((_, i) => <circle key={i} cx={-70 + i * 14} cy={-12 - h(i) * 26} r={4} fill="#EDEFF3" />)}
            </g>
          )}
          {s > HORNEAR && Array.from({length: 7}).map((_, i) => {
            const t = s - HORNEAR - i * 0.12;
            if (t < 0 || t > 1.1) return null;
            return <circle key={'pg' + i} cx={720 + i * 9 + Math.sin(t * 6 + i) * 6} cy={380 + t * 160} r={5} fill="#fff" opacity={1 - t / 1.1} />;
          })}
          {/* célula quemada: brilla y humea */}
          {s > QUEMA && s < CAMBIA + 0.6 && <circle cx={CX(5)} cy={955} r={150 + golpe(s, QUEMA, 12, 4) * 20} fill={QUEMADO} opacity={0.28 * Math.min(1, hum * 3)} />}
          {hum > 0 && Array.from({length: 6}).map((_, i) => {
            const t = hum - i * 0.28;
            if (t < 0) return null;
            const k = t % 1.7;
            return <circle key={'hu' + i} cx={CX(5) + Math.sin(k * 3 + i) * 26} cy={860 - k * 90} r={18 + k * 16} fill="rgba(70,55,55,0.5)" opacity={Math.max(0, 1 - k / 1.7)} />;
          })}
          {/* curita tachada */}
          {s > NO2 - 0.05 && s < CAMBIA + 0.4 && (
            <g opacity={1 - lin(CAMBIA, CAMBIA + 0.35, 0, 1)}>
              <g transform={`translate(${CX(5)} 960) rotate(-35) scale(${spr(NO2, 10, 150)})`}>
                <rect x={-100} y={-32} width={200} height={64} rx={32} fill="#F2CFA0" stroke="#B98B5A" strokeWidth={5} />
                <rect x={-36} y={-32} width={72} height={64} fill="#EBDDC4" stroke="#B98B5A" strokeWidth={3} />
                {[-74, -58, 58, 74].map((dx, i) => <circle key={i} cx={dx} cy={i % 2 ? 8 : -8} r={4} fill="#B98B5A" />)}
              </g>
              <line x1={CX(5) - 70} y1={890} x2={CX(5) - 70 + 140 * lin(REPARA, REPARA + 0.2, 0, 1)} y2={890 + 140 * lin(REPARA, REPARA + 0.2, 0, 1)} stroke={LIMA} strokeWidth={22} strokeLinecap="round" />
              <line x1={CX(5) + 70} y1={890} x2={CX(5) + 70 - 140 * lin(REPARA + 0.18, REPARA + 0.38, 0, 1)} y2={890 + 140 * lin(REPARA + 0.18, REPARA + 0.38, 0, 1)} stroke={LIMA} strokeWidth={22} strokeLinecap="round" />
            </g>
          )}
          {/* gotita que se cuela y gota protagonista */}
          {s > ALGO - 0.4 && s < QUEMA + 0.05 && <Gota x={T.x} y={T.y} r={28} />}
          <Gota x={gx} y={gy} r={gr} col={gcol} sy={sq} sx={1 + (1 - sq) * 0.8} />
        </Lienzo>
        <Brillo x={540} y={720} r={560} color="rgba(127,200,255,0.75)" t0={MOCO} />
        {s < DIAS + 1.6 && <Contador desde={1} hasta={3} t0={CADA} t1={DIAS + 0.2} x={540} y={440} sufijo=" días" size={74} color={LIMA} />}
        <Ondas x={CX(1)} y={540} t0={CAEN + 0.9} color="#F2FFA0" radio={200} />
        <Ondas x={CX(3)} y={540} t0={CAEN + 1.0} color="#F2FFA0" radio={200} />
        <Ondas x={CX(7)} y={540} t0={CAEN + 1.1} color="#F2FFA0" radio={200} />
      </Camara>
    </AbsoluteFill>
  );
};

