};

// Sitio 4: otra vez el estómago del inicio, ya en paz (E13-E14)
const EstomagoFin: React.FC = () => {
  const {s, lin} = useS();
  const k = lin(ASI, ATACA2, 0, 1, Easing.in(Easing.quad));
  let gx = 780 - 240 * k, gy = 160 + 530 * k, sx = 1, sy = 1;
  if (s > ATACA2) {
    const dt = s - ATACA2;
    const q = Math.max(0, 1 - dt * 6);
    sx = 1 + 0.5 * q; sy = 1 - 0.4 * q;
    const up = lin(ATACA2, ATACA2 + 0.8, 0, 1, Easing.out(Easing.cubic));
    gx = 540 + up * 40 + Math.sin(s * 1.6) * 24;
    gy = 690 - up * 230 + Math.sin(s * 2.4) * 14;
  }
  const hz = interpolate(s, [HIERRO - 0.1, HIERRO + 1.3], [0, 1], clamp);
  return (
    <AbsoluteFill style={{background: '#4A1620'}}>
      <Camara paradas={[{t: ASI, x: 540, y: 960, zoom: 1.0}, {t: ATACA2, x: 540, y: 900, zoom: 1.12}, {t: GANA + 1, x: 540, y: 880, zoom: 1.3}, {t: ESTRENA + 2, x: 540, y: 960, zoom: 1.1}]}>
        <Pliegues claro halo={interpolate(s, [GANA, GANA + 0.4, GANA + 2], [0, 1, 0.4], clamp)} metal={hz > 0 && hz < 1 ? hz : 0} />
        <Lago y0={1560} />
        <Lienzo>
          <Gota x={gx} y={gy} r={62} sx={sx} sy={sy} />
        </Lienzo>
        <Ondas x={540} y={700} t0={ATACA2} color="#FFD9D2" radio={260} />
        <Ondas x={540} y={800} t0={ESTRENA} color="#FFE9E4" radio={520} />
        <Ondas x={540} y={800} t0={ESTRENA + 0.2} color="#FFC9C0" radio={620} />
      </Camara>
    </AbsoluteFill>
  );
};

